    print(f"########## SLIDE {i} ##########")
    for sh in s.shapes:
        print(f"  [shape] name={sh.shape_name if hasattr(sh,'shape_name') else sh.name!r} type={sh.shape_type} has_tf={sh.has_text_frame} has_table={sh.has_table}")
        if sh.has_text_frame:
            for pi, para in enumerate(sh.text_frame.paragraphs):
                t = "".join(r.text for r in para.runs)
                if t.strip(): print(f"     p{pi}: {t!r}")
        if sh.has_table:
            tb = sh.table
            for ri, row in enumerate(tb.rows):
                cells = [c.text for c in row.cells]
                print(f"     r{ri}: {cells}")
